import React, { useEffect, useState } from "react";

const LandingPage = () => {
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [user, setUser] = useState(null);
  const [scrollY, setScrollY] = useState(0);

  useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };

    const handleScroll = () => {
      setScrollY(window.scrollY);
      const navbar = document.querySelector(".navbar");
      if (navbar) {
        navbar.style.background =
          window.scrollY > 50 ? "rgba(10,10,10,0.9)" : "rgba(10,10,10,0.4)";
        navbar.style.backdropFilter =
          window.scrollY > 50 ? "blur(24px)" : "blur(8px)";
      }
    };

    const observerOptions = {
      threshold: 0.15,
      rootMargin: "0px 0px -80px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
        }
      });
    }, observerOptions);

    document.querySelectorAll(".fade-in, .fade-in-up, .scale-in").forEach((el) => 
      observer.observe(el)
    );

    document.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("scroll", handleScroll);

    return () => {
      window.removeEventListener("scroll", handleScroll);
      document.removeEventListener("mousemove", handleMouseMove);
      observer.disconnect();
    };
  }, []);

  const handleNavClick = (section) => {
    console.log(`Navigate to: ${section}`);
  };

  const handleLogout = () => {
    setUser(null);
  };

  const handleLogin = () => {
    setUser({ username: "Demo User" });
  };

  return (
    <>
      <style>
        {`
        * {
          margin: 0;
          padding: 0;
          box-sizing: border-box;
        }

        body {
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
          background: #0a0a0a;
          color: #fff;
          overflow-x: hidden;
        }

        .bg-pattern {
          position: fixed;
          inset: 0;
          background: 
            radial-gradient(circle at 20% 50%, rgba(0, 242, 255, 0.12) 0%, transparent 60%),
            radial-gradient(circle at 80% 20%, rgba(157, 77, 255, 0.12) 0%, transparent 60%),
            radial-gradient(circle at 40% 80%, rgba(0, 255, 153, 0.08) 0%, transparent 60%);
          pointer-events: none;
          z-index: 0;
        }

        .grid-overlay {
          position: fixed;
          inset: 0;
          background-image: 
            linear-gradient(rgba(255,255,255,0.01) 1px, transparent 1px),
            linear-gradient(90deg, rgba(255,255,255,0.01) 1px, transparent 1px);
          background-size: 50px 50px;
          pointer-events: none;
          z-index: 0;
        }

        .spotlight {
          position: fixed;
          width: 800px;
          height: 800px;
          background: radial-gradient(circle, rgba(0, 242, 255, 0.18) 0%, transparent 70%);
          pointer-events: none;
          z-index: 1;
          transform: translate(-50%, -50%);
          transition: opacity 0.3s;
          filter: blur(60px);
        }

        .navbar {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          z-index: 1000;
          padding: 20px 0;
          background: rgba(10,10,10,0.4);
          backdrop-filter: blur(8px);
          border-bottom: 1px solid rgba(255,255,255,0.05);
          transition: all 0.3s ease;
        }

        .nav-container {
          max-width: 1400px;
          margin: 0 auto;
          padding: 0 40px;
          display: flex;
          justify-content: space-between;
          align-items: center;
        }

        .logo {
          font-size: 26px;
          font-weight: 900;
          background: linear-gradient(135deg, #00f2ff, #00ff99);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          letter-spacing: -1px;
          cursor: pointer;
          transition: transform 0.3s ease;
        }

        .logo:hover {
          transform: scale(1.05);
        }

        .nav-menu {
          display: flex;
          gap: 8px;
          align-items: center;
          list-style: none;
        }

        .nav-btn {
          padding: 10px 20px;
          color: #d0d0d0;
          text-decoration: none;
          border-radius: 12px;
          transition: all 0.3s ease;
          font-size: 15px;
          font-weight: 600;
          position: relative;
          cursor: pointer;
          background: transparent;
          border: none;
        }

        .nav-btn:hover {
          color: #00f2ff;
          background: rgba(0, 242, 255, 0.1);
          transform: translateY(-2px);
        }

        .nav-user-text {
          padding: 10px 20px;
          color: #00ff99;
          font-size: 15px;
          font-weight: 600;
        }

        .btn-logout {
          padding: 10px 22px;
          background: rgba(255, 50, 50, 0.1);
          color: #ff6b6b;
          border: 1px solid rgba(255, 50, 50, 0.3);
          border-radius: 12px;
          cursor: pointer;
          font-size: 15px;
          font-weight: 700;
          transition: all 0.3s ease;
        }

        .btn-logout:hover {
          background: rgba(255, 50, 50, 0.2);
          border-color: rgba(255, 50, 50, 0.5);
          transform: translateY(-2px);
        }

        .hero {
          position: relative;
          min-height: 100vh;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 140px 40px 100px;
          z-index: 2;
        }

        .hero-content {
          max-width: 1300px;
          text-align: center;
          opacity: 0;
          transform: translateY(40px);
          transition: all 1.2s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .hero-content.visible {
          opacity: 1;
          transform: translateY(0);
        }

        .hero-badge {
          display: inline-flex;
          align-items: center;
          gap: 10px;
          padding: 10px 24px;
          background: rgba(0, 242, 255, 0.08);
          border: 1px solid rgba(0, 242, 255, 0.2);
          border-radius: 50px;
          font-size: 14px;
          font-weight: 600;
          color: #00f2ff;
          margin-bottom: 32px;
          animation: fadeIn 1s ease 0.3s forwards;
          opacity: 0;
          letter-spacing: 0.5px;
        }

        .badge-dot {
          width: 6px;
          height: 6px;
          background: #00ff99;
          border-radius: 50%;
        }

        .hero-title {
          font-size: clamp(4rem, 10vw, 8rem);
          font-weight: 900;
          line-height: 0.95;
          margin-bottom: 28px;
          background: linear-gradient(135deg, #00f2ff 0%, #00ff99 40%, #9d4dff 100%);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          letter-spacing: -4px;
        }

        .hero-line {
          display: block;
          animation: slideUp 1s cubic-bezier(0.4, 0, 0.2, 1) forwards;
          opacity: 0;
          transform: translateY(60px);
        }

        .hero-line:nth-child(1) { animation-delay: 0.3s; }
        .hero-line:nth-child(2) { animation-delay: 0.5s; }
        .hero-line:nth-child(3) { animation-delay: 0.7s; }

        @keyframes slideUp {
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        .hero-subtitle {
          font-size: clamp(20px, 3vw, 26px);
          color: #b0b0b0;
          margin: 24px auto 0;
          max-width: 700px;
          font-weight: 400;
          letter-spacing: 0.3px;
          line-height: 1.5;
          animation: fadeIn 1s ease 0.9s forwards;
          opacity: 0;
        }

        @keyframes fadeIn {
          to { opacity: 1; }
        }

        .cta-buttons {
          margin-top: 48px;
          display: flex;
          gap: 18px;
          flex-wrap: wrap;
          justify-content: center;
          animation: fadeIn 1s ease 1.1s forwards;
          opacity: 0;
        }

        .btn {
          padding: 18px 38px;
          border-radius: 16px;
          font-size: 17px;
          font-weight: 700;
          cursor: pointer;
          transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
          border: none;
          text-decoration: none;
          position: relative;
          overflow: hidden;
        }

        .btn::before {
          content: '';
          position: absolute;
          inset: 0;
          background: linear-gradient(135deg, rgba(255,255,255,0.15), transparent);
          opacity: 0;
          transition: opacity 0.4s;
        }

        .btn:hover::before {
          opacity: 1;
        }

        .btn-primary {
          background: linear-gradient(135deg, #00f2ff, #00ff99);
          color: #000;
          box-shadow: 0 10px 40px rgba(0, 242, 255, 0.4);
        }

        .btn-primary:hover {
          transform: translateY(-6px);
          box-shadow: 0 16px 50px rgba(0, 242, 255, 0.6);
        }

        .btn-secondary {
          background: rgba(255, 255, 255, 0.06);
          color: #fff;
          border: 2px solid rgba(255, 255, 255, 0.12);
          box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
        }

        .btn-secondary:hover {
          background: rgba(255, 255, 255, 0.12);
          border-color: rgba(255, 255, 255, 0.25);
          transform: translateY(-6px);
        }

        .features-section {
          position: relative;
          padding: 120px 40px;
          z-index: 2;
        }

        .features-container {
          max-width: 1200px;
          margin: 0 auto;
        }

        .section-title {
          font-size: clamp(2.5rem, 5vw, 4rem);
          font-weight: 900;
          text-align: center;
          margin-bottom: 24px;
          background: linear-gradient(135deg, #fff, #808080);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          letter-spacing: -2px;
        }

        .section-subtitle {
          text-align: center;
          font-size: 18px;
          color: #808080;
          margin-bottom: 70px;
          max-width: 600px;
          margin-left: auto;
          margin-right: auto;
        }

        .features-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
          gap: 32px;
          margin-bottom: 80px;
        }

        .feature-card {
          background: rgba(255, 255, 255, 0.02);
          border: 1px solid rgba(255, 255, 255, 0.06);
          border-radius: 24px;
          padding: 48px;
          transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
          position: relative;
          overflow: hidden;
        }

        .feature-card::before {
          content: '';
          position: absolute;
          inset: 0;
          background: linear-gradient(135deg, rgba(0, 242, 255, 0.08), rgba(157, 77, 255, 0.08));
          opacity: 0;
          transition: opacity 0.5s;
        }

        .feature-card:hover {
          transform: translateY(-12px);
          border-color: rgba(0, 242, 255, 0.4);
          box-shadow: 0 24px 70px rgba(0, 242, 255, 0.25);
        }

        .feature-card:hover::before {
          opacity: 1;
        }

        .feature-icon-pro {
          width: 64px;
          height: 64px;
          margin-bottom: 24px;
          display: flex;
          align-items: center;
          justify-content: center;
          background: rgba(0, 242, 255, 0.08);
          border: 1px solid rgba(0, 242, 255, 0.2);
          border-radius: 16px;
          color: #00f2ff;
          position: relative;
          transition: all 0.4s ease;
        }

        .feature-card:hover .feature-icon-pro {
          background: rgba(0, 242, 255, 0.15);
          border-color: rgba(0, 242, 255, 0.4);
          transform: translateY(-4px);
        }

        .feature-title {
          font-size: 28px;
          font-weight: 800;
          margin-bottom: 14px;
          color: #00f2ff;
          position: relative;
        }

        .feature-desc {
          color: #b0b0b0;
          line-height: 1.7;
          font-size: 17px;
          position: relative;
        }

        .testimonials-section {
          position: relative;
          padding: 100px 40px;
          z-index: 2;
        }

        .testimonials-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
          gap: 28px;
          max-width: 1200px;
          margin: 0 auto;
        }

        .testimonial-card {
          background: rgba(255, 255, 255, 0.03);
          border: 1px solid rgba(255, 255, 255, 0.06);
          border-radius: 20px;
          padding: 36px;
          transition: all 0.4s ease;
        }

        .testimonial-card:hover {
          transform: translateY(-8px);
          border-color: rgba(0, 255, 153, 0.3);
          box-shadow: 0 16px 50px rgba(0, 255, 153, 0.15);
        }

        .testimonial-text {
          font-size: 16px;
          line-height: 1.7;
          color: #d0d0d0;
          margin-bottom: 20px;
          font-style: italic;
        }

        .testimonial-author {
          display: flex;
          align-items: center;
          gap: 12px;
        }

        .author-avatar {
          width: 48px;
          height: 48px;
          border-radius: 50%;
          background: linear-gradient(135deg, #00f2ff, #00ff99);
          display: flex;
          align-items: center;
          justify-content: center;
          font-weight: 800;
          font-size: 18px;
          color: #000;
        }

        .author-info h4 {
          font-size: 16px;
          font-weight: 700;
          color: #fff;
          margin-bottom: 4px;
        }

        .author-info p {
          font-size: 14px;
          color: #808080;
        }

        .cta-section {
          position: relative;
          padding: 100px 40px;
          z-index: 2;
        }

        .cta-box {
          max-width: 900px;
          margin: 0 auto;
          background: linear-gradient(135deg, rgba(0, 242, 255, 0.08), rgba(157, 77, 255, 0.08));
          border: 1px solid rgba(0, 242, 255, 0.2);
          border-radius: 32px;
          padding: 80px 60px;
          text-align: center;
          position: relative;
          overflow: hidden;
        }

        .cta-box::before {
          content: '';
          position: absolute;
          inset: 0;
          background: radial-gradient(circle at 50% 0%, rgba(0, 242, 255, 0.15), transparent 70%);
        }

        .cta-title {
          font-size: clamp(2.5rem, 5vw, 4rem);
          font-weight: 900;
          margin-bottom: 20px;
          background: linear-gradient(135deg, #00f2ff, #00ff99);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          position: relative;
        }

        .cta-text {
          font-size: 20px;
          color: #b0b0b0;
          margin-bottom: 40px;
          position: relative;
        }

        .floating-words {
          position: fixed;
          inset: 0;
          pointer-events: none;
          z-index: 1;
          overflow: hidden;
        }

        .word {
          position: absolute;
          color: rgba(255, 255, 255, 0.025);
          font-size: clamp(15px, 2vw, 20px);
          font-weight: 700;
          font-family: 'Courier New', monospace;
          animation: float 25s infinite ease-in-out;
          white-space: nowrap;
        }

        @keyframes float {
          0%, 100% {
            transform: translateY(0) rotate(0deg);
            opacity: 0;
          }
          10% {
            opacity: 1;
          }
          90% {
            opacity: 1;
          }
          100% {
            transform: translateY(-110vh) rotate(360deg);
            opacity: 0;
          }
        }

        .fade-in-up {
          opacity: 0;
          transform: translateY(40px);
          transition: all 0.9s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .fade-in-up.visible {
          opacity: 1;
          transform: translateY(0);
        }

        .scale-in {
          opacity: 0;
          transform: scale(0.9);
          transition: all 0.8s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .scale-in.visible {
          opacity: 1;
          transform: scale(1);
        }

        @media (max-width: 768px) {
          .nav-menu {
            flex-wrap: wrap;
            gap: 6px;
          }
          
          .nav-btn, .nav-user-text {
            padding: 8px 16px;
            font-size: 14px;
          }

          .hero {
            padding: 120px 20px 80px;
          }

          .hero-title {
            letter-spacing: -2px;
          }

          .cta-buttons {
            gap: 14px;
          }

          .btn {
            padding: 16px 28px;
            font-size: 16px;
          }

          .features-grid {
            grid-template-columns: 1fr;
            gap: 24px;
          }

          .feature-card {
            padding: 36px;
          }

          .cta-box {
            padding: 60px 40px;
          }
        }
      `}
      </style>

      <div className="bg-pattern"></div>
      <div className="grid-overlay"></div>
      <div 
        className="spotlight" 
        style={{
          left: `${mousePosition.x}px`,
          top: `${mousePosition.y}px`,
        }}
      ></div>

      {/* Navigation */}
      <nav className="navbar">
        <div className="nav-container">
          <div className="logo" onClick={() => handleNavClick('home')}>CodeGen4Future</div>

          <ul className="nav-menu">
            <li><button onClick={() => handleNavClick('about')} className="nav-btn">About</button></li>
            <li><button onClick={() => handleNavClick('problems')} className="nav-btn">Problems</button></li>
            <li><button onClick={() => handleNavClick('contests')} className="nav-btn">Contests</button></li>
            <li><button onClick={() => handleNavClick('leaderboard')} className="nav-btn">Leaderboard</button></li>

            {user ? (
              <>
                <li><button onClick={() => handleNavClick('profile')} className="nav-btn">Profile</button></li>
                <li><span className="nav-user-text">Hi, {user.username}</span></li>
                <li><button className="btn-logout" onClick={handleLogout}>Logout</button></li>
              </>
            ) : (
              <>
                <li><button onClick={handleLogin} className="nav-btn">Login</button></li>
                <li><button onClick={() => handleNavClick('register')} className="nav-btn">Register</button></li>
              </>
            )}
          </ul>
        </div>
      </nav>

      {/* Hero Section */}
      <section className="hero">
        <div className="hero-content fade-in">
          <h1 className="hero-title">
            <span className="hero-line">Code,</span>
            <span className="hero-line">Compete,</span>
            <span className="hero-line">Conquer</span>
          </h1>

          <p className="hero-subtitle">
            A competitive programming platform for students and developers
          </p>

          <div className="cta-buttons">
            <button onClick={() => handleNavClick('problems')} className="btn btn-primary">Start Solving</button>
            <button onClick={() => handleNavClick('editor')} className="btn btn-primary">Live Editor</button>
            <button onClick={() => handleNavClick('contests')} className="btn btn-secondary">Browse Contests</button>
            <button onClick={() => handleNavClick('duel')} className="btn btn-secondary">1v1 Challenge</button>
          </div>
        </div>
      </section>

      {/* Features Section */}
      <section className="features-section">
        <div className="features-container">
          <h2 className="section-title fade-in-up">Platform Features</h2>
          <p className="section-subtitle fade-in-up">Comprehensive tools for competitive programming</p>
          
          <div className="features-grid">
            <div className="feature-card fade-in-up">
              <div className="feature-icon-pro">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <polyline points="22 12 18 12 15 21 9 3 6 12 2 12"></polyline>
                </svg>
              </div>
              <h3 className="feature-title">High Performance</h3>
              <p className="feature-desc">Execute code in milliseconds with our optimized compiler infrastructure. Built for speed and reliability.</p>
            </div>

            <div className="feature-card fade-in-up">
              <div className="feature-icon-pro">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path>
                  <circle cx="9" cy="7" r="4"></circle>
                  <path d="M23 21v-2a4 4 0 0 0-3-3.87"></path>
                  <path d="M16 3.13a4 4 0 0 1 0 7.75"></path>
                </svg>
              </div>
              <h3 className="feature-title">Live Competitions</h3>
              <p className="feature-desc">Participate in real-time programming contests with global rankings and detailed performance metrics.</p>
            </div>

            <div className="feature-card fade-in-up">
              <div className="feature-icon-pro">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path>
                  <polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline>
                  <line x1="12" y1="22.08" x2="12" y2="12"></line>
                </svg>
              </div>
              <h3 className="feature-title">Adaptive Learning</h3>
              <p className="feature-desc">Curated problem sets that scale with your expertise. From fundamentals to advanced data structures.</p>
            </div>

            <div className="feature-card fade-in-up">
              <div className="feature-icon-pro">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
                  <line x1="9" y1="3" x2="9" y2="21"></line>
                </svg>
              </div>
              <h3 className="feature-title">Head-to-Head Challenges</h3>
              <p className="feature-desc">Compete directly with other developers in timed coding challenges. Test your skills in real scenarios.</p>
            </div>

            <div className="feature-card fade-in-up">
              <div className="feature-icon-pro">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <line x1="18" y1="20" x2="18" y2="10"></line>
                  <line x1="12" y1="20" x2="12" y2="4"></line>
                  <line x1="6" y1="20" x2="6" y2="14"></line>
                </svg>
              </div>
              <h3 className="feature-title">Performance Analytics</h3>
              <p className="feature-desc">Comprehensive insights into your coding patterns, problem-solving efficiency, and skill progression.</p>
            </div>

            <div className="feature-card fade-in-up">
              <div className="feature-icon-pro">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path>
                  <circle cx="9" cy="7" r="4"></circle>
                  <path d="M23 21v-2a4 4 0 0 0-3-3.87"></path>
                  <path d="M16 3.13a4 4 0 0 1 0 7.75"></path>
                  <circle cx="17" cy="11" r="3"></circle>
                </svg>
              </div>
              <h3 className="feature-title">Team Collaboration</h3>
              <p className="feature-desc">Organize team-based competitions and collaborative problem-solving sessions with built-in coordination tools.</p>
            </div>
          </div>
        </div>
      </section>



      {/* Floating Words */}
      <div className="floating-words">
        {[
          "console.log","return","import","function","class","debug","await",
          "merge","deploy","API","boolean","array.map","forEach","useState","git push",
          "async","const","let","if","else","for","while"
        ].map((w, i) => (
          <span key={i} className="word" style={{
            left: `${3 + (i * 5)}%`,
            top: `${10 + (i * 2.5)}%`,
            animationDelay: `${i * 0.9}s`
          }}>{w}</span>
        ))}
      </div>
    </>
  );
};

export default LandingPage;
